// src/components/ROI/ProjectForm.js

import React, { useEffect, useState } from "react";
import axios from "axios";
// Keeping CSS import path as previously used in your project
import "../../styles/RecordEntry.css";

// Timestamp helper (YYYY-MM-DD HH:MM:SS)
function nowSQLite() {
  const d = new Date();
  const pad = (n) => String(n).padStart(2, "0");
  return `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())} ${pad(
    d.getHours()
  )}:${pad(d.getMinutes())}:${pad(d.getSeconds())}`;
}

// Date helper for intake_entry_date (YYYY-MM-DD)
function todayISODate() {
  const d = new Date();
  const pad = (n) => String(n).padStart(2, "0");
  return `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}`;
}

// Minimal CSV parser with quoted fields
function parseCSV(text) {
  const rows = [];
  let cur = [];
  let field = "";
  let inQuotes = false;

  for (let i = 0; i < text.length; i++) {
    const ch = text[i];
    if (inQuotes) {
      if (ch === `"`) {
        if (text[i + 1] === `"`) {
          field += `"`;
          i++;
        } else {
          inQuotes = false;
        }
      } else {
        field += ch;
      }
    } else {
      if (ch === `"`) {
        inQuotes = true;
      } else if (ch === ",") {
        cur.push(field);
        field = "";
      } else if (ch === "\n") {
        cur.push(field);
        field = "";
        if (cur.length > 1 || (cur.length === 1 && cur[0] !== "")) rows.push(cur);
        cur = [];
      } else if (ch === "\r") {
        // ignore
      } else {
        field += ch;
      }
    }
  }
  if (field.length || cur.length) {
    cur.push(field);
    rows.push(cur);
  }
  return rows;
}

const normalizeHeader = (s) =>
  (s || "").toString().trim().replace(/\*/g, "").replace(/:/g, "").toLowerCase();

const EXPECTED_HEADERS = [
  "intake number",
  "intake name",
  "qa assignee",
  "manager",
  "pat assignee",
  "status/eta",
];

// CSV/UI -> DB mapping
const CSV_TO_DB = {
  "intake number": { table: "projects", column: "intake_number" },
  "intake name": { table: "projects", column: "intake_name" },
  "qa assignee": { table: "projects", column: "FuncSME" },
  manager: { table: "projects", column: "QAManager" },
  "pat assignee": { table: "projects", column: "PATAssignee" },
  "status/eta": { table: "projects", column: "AutoEstimateDueDate" },
};

const ProjectForm = () => {
  // Only the seven requested top-level fields (not used for bulk insert)
  const [form, setForm] = useState({
    intake_number: "",
    intake_name: "",
    qa_assignee: "",
    manager: "",
    automation_qe_lead: "",
    pat_assignee: "",
    status_eta: "",
  });

  const [csvFile, setCsvFile] = useState(null);
  const [rows, setRows] = useState([]); // parsed rows for grid
  const [uploading, setUploading] = useState(false);
  const [message, setMessage] = useState("");

  // Per-row notes (e.g., "Project Already Exists...")
  const [rowNotes, setRowNotes] = useState({}); // { [rowIndex]: string }

  // Resources for the "Estimate Assigned to" dropdown
  const [resources, setResources] = useState([]);
  useEffect(() => {
    (async () => {
      try {
        const res = await axios.get("http://localhost:5000/api/resourcefetch");
        const list =
          Array.isArray(res.data?.resources) ? res.data.resources :
          Array.isArray(res.data) ? res.data : [];
        setResources(list);
      } catch (e) {
        console.error("Failed to fetch resources", e);
      }
    })();
  }, []);

  const onChangeField = (e) => {
    const { name, value } = e.target;
    setForm((s) => ({ ...s, [name]: value }));
  };

  // Parse the CSV and populate rows
  const parseAndSetFromFile = async (file) => {
    setMessage("");
    setRowNotes({});
    if (!file) {
      setRows([]);
      return;
    }

    const text = await file.text();
    const raw = parseCSV(text);
    if (!raw.length) {
      setRows([]);
      setMessage("CSV appears empty.");
      return;
    }

    const header = raw[0].map(normalizeHeader);
    const body = raw.slice(1);

    const idx = {};
    EXPECTED_HEADERS.forEach((key) => {
      const i = header.findIndex((h) => h === key);
      idx[key] = i >= 0 ? i : -1;
    });

    const missing = Object.entries(idx)
      .filter(([_, i]) => i === -1)
      .map(([k]) => k);
    if (missing.length) {
      setMessage(`Missing expected columns in CSV: ${missing.join(", ")}`);
      // continue with available columns
    }

    const parsed = body
      .map((arr) => {
        const get = (key) => {
          const i = idx[key];
          return i >= 0 ? (arr[i] || "").trim() : "";
        };
        const record = {
          intake_number: get("intake number"),
          intake_name: get("intake name"),
          qa_assignee: get("qa assignee"),
          manager: get("manager"),
          pat_assignee: get("pat assignee"),
          status_eta: get("status/eta"),
          estimate_assigned_to: "",
        };
        const nonEmpty = Object.values(record).some((v) => String(v).length);
        return nonEmpty ? record : null;
      })
      .filter(Boolean);

    setRows(parsed);
    setMessage(parsed.length ? "CSV Parsed below" : "No valid data rows found in CSV.");
  };

  // Auto-parse when file selected
  const onPickCSV = (e) => {
    const f = e.target?.files?.[0] || null;
    setCsvFile(f);
    if (f) {
      parseAndSetFromFile(f);
    } else {
      setRows([]);
      setRowNotes({});
      setMessage("");
    }
  };

  // Kept for compatibility (manual parse button)
  const onParseCSV = async () => {
    if (!csvFile) return;
    await parseAndSetFromFile(csvFile);
  };

  // Upload parsed rows
  const onUpload = async () => {
    if (!rows.length) {
      setMessage("Nothing to upload. Please select a CSV first.");
      return;
    }
    setUploading(true);
    setMessage("");
    setRowNotes({});

    try {
      for (let i = 0; i < rows.length; i++) {
        const row = rows[i];
        const intakeNum = (row.intake_number || "").trim();
        const intakeName = (row.intake_name || "").trim();
        if (!intakeNum) continue;

        // Check if project already exists; if yes, show message and skip
        try {
          const exists = await axios.get(
            `http://localhost:5000/api/projects/${encodeURIComponent(intakeNum)}`
          );
          if (exists && exists.status === 200) {
            setRowNotes((m) => ({
              ...m,
              [i]: "Project Already Exists, Update via Project Status Tab",
            }));
            continue;
          }
        } catch (err) {
          // 404 => not found; proceed. Other errors: proceed to insert attempt.
          if (err?.response?.status !== 404) {
            // proceed anyway
          }
        }

        const updates = [];
        // Map CSV fields to DB columns
        Object.entries(CSV_TO_DB).forEach(([key, cfg]) => {
          const v =
            key === "intake number" ? intakeNum :
            key === "intake name" ? intakeName :
            key === "qa assignee" ? row.qa_assignee :
            key === "manager" ? row.manager :
            key === "pat assignee" ? row.pat_assignee :
            key === "status/eta" ? row.status_eta : "";
          updates.push({ table: cfg.table, column: cfg.column, value: v });
        });

        // Estimate Assigned to -> projects.EstimateAssignedTo
        updates.push({
          table: "projects",
          column: "EstimateAssignedTo",
          value: (row.estimate_assigned_to || "").trim(),
        });

        // Intake entry date -> projects.intake_entry_date
        updates.push({
          table: "projects",
          column: "intake_entry_date",
          value: todayISODate(),
        });

        // Status + timestamp
        updates.push({
          table: "projects",
          column: "AutoEstimateStatus",
          value: "Not Yet Assigned",
        });
        updates.push({
          table: "projects",
          column: "timestamp",
          value: nowSQLite(),
        });

        // POST once per intake (insert if new)
        await axios.post("http://localhost:5000/api/projectmasterupdate", {
          intake_number: intakeNum,
          updates,
        });
      }

      setMessage(`Uploaded ${rows.length} intake(s) successfully.`);
    } catch (e) {
      console.error("Bulk upload failed", e);
      setMessage("Upload failed. Check console/network logs.");
    } finally {
      setUploading(false);
    }
  };

  return (
    <div className="form-page">
      <h2>Intake Entry</h2>

      {/* The 7 UI fields */}
      <div className="section">
        <div className="form-row">
          <div className="form-column">
            <label>*Intake Number:</label>
            <input
              type="text"
              name="intake_number"
              value={form.intake_number}
              onChange={onChangeField}
              placeholder="e.g. INTAKE-0001"
              required
            />
          </div>
          <div className="form-column">
            <label>*Intake Name:</label>
            <input
              type="text"
              name="intake_name"
              value={form.intake_name}
              onChange={onChangeField}
              placeholder="e.g. Payments Modernization"
              required
            />
          </div>
        </div>

        <div className="form-row">
          <div className="form-column">
            <label>QA Assignee</label>
            <input
              type="text"
              name="qa_assignee"
              value={form.qa_assignee}
              onChange={onChangeField}
              placeholder="Name"
            />
          </div>
          <div className="form-column">
            <label>Manager</label>
            <input
              type="text"
              name="manager"
              value={form.manager}
              onChange={onChangeField}
              placeholder="Name"
            />
          </div>
        </div>

        <div className="form-row">
          <div className="form-column">
            <label>*Automation QE Lead:</label>
            <input
              type="text"
              name="automation_qe_lead"
              value={form.automation_qe_lead}
              onChange={onChangeField}
              placeholder="Name"
              required
            />
          </div>
          <div className="form-column">
            <label>PAT Assignee</label>
            <input
              type="text"
              name="pat_assignee"
              value={form.pat_assignee}
              onChange={onChangeField}
              placeholder="Name"
            />
          </div>
        </div>

        <div className="form-row">
          <div className="form-column">
            <label>Status/ETA</label>
            <input
              type="text"
              name="status_eta"
              value={form.status_eta}
              onChange={onChangeField}
              placeholder="YYYY-MM-DD or text"
            />
          </div>
        </div>
      </div>

      {/* Bulk upload controls */}
      <div className="section">
        <div
          className="form-row form-type-row"
          style={{ justifyContent: "space-between" }}
        >
          <button
            type="button"
            onClick={() => document.getElementById("csvPicker").click()}
          >
            Bulk Upload Intakes
          </button>
          <input
            id="csvPicker"
            type="file"
            accept=".csv,text/csv"
            style={{ display: "none" }}
            onChange={onPickCSV} // auto-parses on select
          />
          <div style={{ display: "flex", gap: 8 }}>
            <button type="button" onClick={onParseCSV} disabled={!csvFile}>
              Parse CSV
            </button>
            {/* Upload enabled only after CSV parsed successfully */}
            <button
              type="button"
              onClick={onUpload}
              disabled={!rows.length || uploading}
            >
              {uploading ? "Uploading..." : "Upload"}
            </button>
          </div>
        </div>

        {message && (
          <div
            className="error-message"
            style={{
              color: message.includes("failed") ? "#c00" : "#064",
              marginTop: 8,
            }}
          >
            {message}
          </div>
        )}

        {/* Parsed grid + per-row "exists" notes */}
        <div className="section" style={{ overflowX: "auto" }}>
          <table className="min-w-full table-fixed" style={{ width: "100%" }}>
            <thead>
              <tr>
                <th style={{ textAlign: "left", padding: 8 }}>*Intake Number:</th>
                <th style={{ textAlign: "left", padding: 8 }}>*Intake Name:</th>
                <th style={{ textAlign: "left", padding: 8 }}>QA Assignee</th>
                <th style={{ textAlign: "left", padding: 8 }}>Manager</th>
                <th style={{ textAlign: "left", padding: 8 }}>PAT Assignee</th>
                <th style={{ textAlign: "left", padding: 8 }}>Status/ETA</th>
                <th style={{ textAlign: "left", padding: 8 }}>Estimate Assigned to</th>
              </tr>
            </thead>
            <tbody>
              {rows.length ? (
                rows.map((r, i) => (
                  <React.Fragment key={`${r.intake_number}-${i}`}>
                    <tr>
                      <td style={{ padding: 8 }}>
                        <input
                          type="text"
                          value={r.intake_number}
                          onChange={(e) =>
                            setRows((rs) =>
                              rs.map((x, ix) =>
                                ix === i ? { ...x, intake_number: e.target.value } : x
                              )
                            )
                          }
                        />
                      </td>
                      <td style={{ padding: 8 }}>
                        <input
                          type="text"
                          value={r.intake_name}
                          onChange={(e) =>
                            setRows((rs) =>
                              rs.map((x, ix) =>
                                ix === i ? { ...x, intake_name: e.target.value } : x
                              )
                            )
                          }
                        />
                      </td>
                      <td style={{ padding: 8 }}>
                        <input
                          type="text"
                          value={r.qa_assignee}
                          onChange={(e) =>
                            setRows((rs) =>
                              rs.map((x, ix) =>
                                ix === i ? { ...x, qa_assignee: e.target.value } : x
                              )
                            )
                          }
                        />
                      </td>
                      <td style={{ padding: 8 }}>
                        <input
                          type="text"
                          value={r.manager}
                          onChange={(e) =>
                            setRows((rs) =>
                              rs.map((x, ix) =>
                                ix === i ? { ...x, manager: e.target.value } : x
                              )
                            )
                          }
                        />
                      </td>
                      <td style={{ padding: 8 }}>
                        <input
                          type="text"
                          value={r.pat_assignee}
                          onChange={(e) =>
                            setRows((rs) =>
                              rs.map((x, ix) =>
                                ix === i ? { ...x, pat_assignee: e.target.value } : x
                              )
                            )
                          }
                        />
                      </td>
                      <td style={{ padding: 8 }}>
                        <input
                          type="text"
                          value={r.status_eta}
                          onChange={(e) =>
                            setRows((rs) =>
                              rs.map((x, ix) =>
                                ix === i ? { ...x, status_eta: e.target.value } : x
                              )
                            )
                          }
                        />
                      </td>
                      <td style={{ padding: 8 }}>
                        <select
                          value={r.estimate_assigned_to || ""}
                          onChange={(e) =>
                            setRows((rs) =>
                              rs.map((x, ix) =>
                                ix === i
                                  ? { ...x, estimate_assigned_to: e.target.value }
                                  : x
                              )
                            )
                          }
                        >
                          <option value="">-- Select --</option>
                          {resources.map((name) => (
                            <option key={name} value={name}>
                              {name}
                            </option>
                          ))}
                        </select>
                      </td>
                    </tr>
                    {rowNotes[i] && (
                      <tr>
                        <td colSpan={7} style={{ padding: 6, color: "#9a3412", fontSize: 12 }}>
                          {rowNotes[i]}
                        </td>
                      </tr>
                    )}
                  </React.Fragment>
                ))
              ) : (
                <tr>
                  <td colSpan={7} style={{ padding: 12, color: "#555" }}>
                    No rows parsed yet. Choose a CSV and it will parse automatically (or click <strong>Parse CSV</strong>).
                  </td>
                </tr>
              )}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
};

export default ProjectForm;
